    "id": "research-how-to-decide-under-uncertainty",
    "title": "How to decide under uncertainty",
    "url": "https://lmdlifers.github.io/TonyKoo/research/how-to-decide-under-uncertainty.html",
    "path": "research/how-to-decide-under-uncertainty.html",
